    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    # Rays mark whole rows/columns; any 2-component hit by a ray changes to 1.
    hit = set()
    for r, c in markers:
        for j in range(w):
            out[r][j] = 1
            if grid[r][j] == 2: hit.add((r, j))
        for i in range(h):
            out[i][c] = 1
            if grid[i][c] == 2: hit.add((i, c))
    seen = set()
    for r, c in hit:
        if (r, c) in seen: continue
        stack = [(r, c)]; comp = []
        seen.add((r, c))
        while stack:
            y, x = stack.pop(); comp.append((y, x))
            for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                    seen.add((ny,nx)); stack.append((ny,nx))
        for y, x in comp: out[y][x] = 1
    return out
